//! Run a parser generated by Shipstern (`include_shipstern_parser!`, 0.9 to 0.12) or Vixen
//! (`include_vixen_parser!`, 0.6 to 0.7) as the decoder under test of `idl-verify --decoder`.
//!
//! Add one binary to the crate that holds your parser:
//!
//! ```ignore
//! fn main() -> std::io::Result<()> {
//!     idl_verify_shipstern::serve!(shipstern, my_crate::pump::AccountParser, my_crate::pump::InstructionParser)
//! }
//! ```
//!
//! Use `vixen` in place of `shipstern` for Vixen, and leave out the instruction parser for an
//! IDL that declares no instructions. To check events too, build the parser with the
//! `program-events` feature and pass `my_crate::pump::resolve_event_default` as a fourth
//! argument. Then run `idl-verify --idl idl.json --decoder ./target/debug/<bin>`.
//!
//! The crate that calls `serve!` needs `shipstern-core` (or `yellowstone-vixen-core`) as a
//! direct dependency: the macro names it.

mod debug;

/// Serve idl-verify's decoder protocol on stdin and stdout with the given parsers.
///
/// - `shipstern`: Shipstern 0.9 to 0.12.
/// - `vixen`: Vixen 0.6 to 0.7.
///
/// Both read the parsers' `Debug` output, which every generated type derives in every version.
#[macro_export]
macro_rules! serve {
    (shipstern, $($parsers:tt)*) => {
        $crate::__decoder!(shipstern_core, $($parsers)*)
    };
    (vixen, $($parsers:tt)*) => {
        $crate::__decoder!(yellowstone_vixen_core, $($parsers)*)
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __decoder {
    (@account_fn $core:ident) => {
        fn account(
            &self,
            owner: [u8; 32],
            pubkey: [u8; 32],
            data: ::std::vec::Vec<u8>,
        ) -> ::core::result::Result<$crate::__private::Value, ::std::string::String> {
            let update = ::$core::AccountUpdate {
                account: ::core::option::Option::Some(::$core::AccountUpdateInfo {
                    pubkey: pubkey.to_vec(),
                    owner: owner.to_vec(),
                    data,
                    ..::core::default::Default::default()
                }),
                ..::core::default::Default::default()
            };
            let parsed = $crate::__private::ready(::$core::Parser::parse(&self.0, &update))?
                .map_err(|e| ::std::format!("{e:?}"))?;
            $crate::__private::account(&parsed)
        }
    };
    (@with $core:ident, $accounts:expr, $instructions:expr, ($data:ident) => $event_body:expr) => {{
        struct Decoder<A, I>(A, I);
        impl<A, I> $crate::__private::Decode for Decoder<A, I>
        where
            A: ::$core::Parser<Input = ::$core::AccountUpdate>,
            A::Output: ::core::fmt::Debug,
            I: ::$core::Parser<Input = ::$core::instruction::InstructionUpdate>,
            I::Output: ::core::fmt::Debug,
        {
            $crate::__decoder!(@account_fn $core);
            fn instruction(
                &self,
                program: [u8; 32],
                accounts: ::std::vec::Vec<[u8; 32]>,
                data: ::std::vec::Vec<u8>,
            ) -> ::core::option::Option<::core::result::Result<$crate::__private::Value, ::std::string::String>> {
                let update = ::$core::instruction::InstructionUpdate {
                    program: ::$core::KeyBytes(program),
                    accounts: accounts.into_iter().map(::$core::KeyBytes).collect(),
                    data,
                    shared: ::core::default::Default::default(),
                    inner: ::std::vec::Vec::new(),
                    // A sample is one instruction, not a transaction: a top-level path, no logs.
                    path: ::core::convert::From::from(::std::vec![0u32]),
                    log_range: 0..0,
                };
                ::core::option::Option::Some(
                    $crate::__private::ready(::$core::Parser::parse(&self.1, &update))
                        .and_then(|parsed| parsed.map_err(|e| ::std::format!("{e:?}")))
                        .and_then(|parsed| $crate::__private::instruction(&parsed)),
                )
            }
            fn event(
                &self,
                $data: &[u8],
            ) -> ::core::option::Option<::core::result::Result<$crate::__private::Value, ::std::string::String>> {
                $event_body
            }
        }
        $crate::__private::run(&Decoder($accounts, $instructions))
    }};
    (@accounts $core:ident, $accounts:expr) => {{
        struct Decoder<A>(A);
        impl<A> $crate::__private::Decode for Decoder<A>
        where
            A: ::$core::Parser<Input = ::$core::AccountUpdate>,
            A::Output: ::core::fmt::Debug,
        {
            $crate::__decoder!(@account_fn $core);
            fn instruction(
                &self,
                _: [u8; 32],
                _: ::std::vec::Vec<[u8; 32]>,
                _: ::std::vec::Vec<u8>,
            ) -> ::core::option::Option<::core::result::Result<$crate::__private::Value, ::std::string::String>> {
                ::core::option::Option::None
            }
            fn event(
                &self,
                _: &[u8],
            ) -> ::core::option::Option<::core::result::Result<$crate::__private::Value, ::std::string::String>> {
                ::core::option::Option::None
            }
        }
        $crate::__private::run(&Decoder($accounts))
    }};
    ($core:ident, $accounts:expr, $instructions:expr, $events:path $(,)?) => {
        $crate::__decoder!(@with $core, $accounts, $instructions, (data) =>
            ::core::option::Option::Some(
                $events(&[], data)
                    .map_err(|e| ::std::format!("{e:?}"))
                    .and_then(|parsed| $crate::__private::instruction(&parsed))))
    };
    ($core:ident, $accounts:expr, $instructions:expr $(,)?) => {
        $crate::__decoder!(@with $core, $accounts, $instructions, (_data) =>
            ::core::option::Option::None)
    };
    ($core:ident, $accounts:expr $(,)?) => {
        $crate::__decoder!(@accounts $core, $accounts)
    };
}

#[doc(hidden)]
pub mod __private {
    use std::any::Any;
    use std::future::Future;
    use std::io::{self, BufRead, Write};
    use std::panic::{self, AssertUnwindSafe};
    use std::pin::pin;
    use std::task::{Context, Poll, Waker};

    use base64::engine::general_purpose::STANDARD;
    use base64::Engine;
    use serde_json::json;
    pub use serde_json::Value;

    /// What `serve!` builds in the user's crate, against their own core crate.
    pub trait Decode {
        fn account(
            &self,
            owner: [u8; 32],
            pubkey: [u8; 32],
            data: Vec<u8>,
        ) -> Result<Value, String>;
        /// `None` when `serve!` got no instruction parser.
        fn instruction(
            &self,
            program: [u8; 32],
            accounts: Vec<[u8; 32]>,
            data: Vec<u8>,
        ) -> Option<Result<Value, String>>;
        /// `None` when `serve!` got no event parser.
        fn event(&self, data: &[u8]) -> Option<Result<Value, String>>;
    }

    // Why a sample is skipped, not failed: a parser without one kind still checks the rest.
    const NO_INSTRUCTION_PARSER: &str = "serve! got no instruction parser; pass \
        `<program module>::InstructionParser` as a third argument";
    const NO_EVENT_PARSER: &str = "serve! got no event parser; build the parser with the \
        `program-events` feature and pass `<program module>::resolve_event_default` as a fourth argument";

    enum Reply {
        Ok(Value),
        Error(String),
        Skip(&'static str),
    }

    /// The output of a parse future. A generated parser does not wait on I/O, so one poll
    /// ends it, and no async runtime is necessary.
    ///
    /// # Errors
    ///
    /// When the future is not ready after the first poll.
    pub fn ready<F: Future>(future: F) -> Result<F::Output, String> {
        match pin!(future).poll(&mut Context::from_waker(Waker::noop())) {
            Poll::Ready(output) => Ok(output),
            Poll::Pending => Err("the parser did not finish on the first poll, and serve! \
                runs no async runtime"
                .into()),
        }
    }

    /// # Errors
    ///
    /// When stdin or stdout fails.
    pub fn run<D: Decode>(decoder: &D) -> io::Result<()> {
        serve(decoder, io::stdin().lock(), io::stdout().lock())
    }

    fn serve<D: Decode>(
        decoder: &D,
        input: impl BufRead,
        mut output: impl Write,
    ) -> io::Result<()> {
        for line in input.lines() {
            let line = line?;
            if line.trim().is_empty() {
                continue;
            }
            // A panic gets an error reply, so idl-verify still writes its report.
            let reply = panic::catch_unwind(AssertUnwindSafe(|| answer(decoder, &line)))
                .unwrap_or_else(|payload| Err(panicked(payload.as_ref())))
                .unwrap_or_else(Reply::Error);
            let reply = match reply {
                Reply::Ok(value) => json!({ "status": "ok", "value": value }),
                Reply::Error(error) => json!({ "status": "error", "error": error }),
                Reply::Skip(reason) => json!({ "status": "skip", "reason": reason }),
            };
            writeln!(output, "{reply}")?;
            output.flush()?;
        }
        Ok(())
    }

    fn panicked(payload: &(dyn Any + Send)) -> String {
        let message = payload
            .downcast_ref::<&str>()
            .copied()
            .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
            .unwrap_or("no message");
        format!("the parser panicked: {message}")
    }

    fn answer<D: Decode>(decoder: &D, line: &str) -> Result<Reply, String> {
        let skip_if_none = |result: Option<Result<Value, String>>, reason| match result {
            Some(result) => result.map(Reply::Ok),
            None => Ok(Reply::Skip(reason)),
        };
        let req: Value = serde_json::from_str(line).map_err(|e| format!("{e:?}"))?;
        let data = STANDARD
            .decode(req["data"].as_str().unwrap_or_default())
            .map_err(|e| format!("{e:?}"))?;
        // idl-verify names the program in every request; the parsers cannot report it.
        let program = key(req["program"]
            .as_str()
            .ok_or("the request names no program; use a newer idl-verify")?)?;
        match req["kind"].as_str() {
            Some("account") => {
                // The protocol allows an empty address, and the parsers do not read it.
                let address = match req["address"].as_str().unwrap_or_default() {
                    "" => [0; 32],
                    address => key(address)?,
                };
                decoder.account(program, address, data).map(Reply::Ok)
            }
            Some("instruction") => {
                let accounts = req["accounts"]
                    .as_array()
                    .map(Vec::as_slice)
                    .unwrap_or_default()
                    .iter()
                    .map(|k| key(k.as_str().unwrap_or_default()))
                    .collect::<Result<Vec<_>, _>>()?;
                skip_if_none(
                    decoder.instruction(program, accounts, data),
                    NO_INSTRUCTION_PARSER,
                )
            }
            Some("event") => skip_if_none(decoder.event(&data), NO_EVENT_PARSER),
            _ => Err("unknown kind".into()),
        }
    }

    fn key(s: &str) -> Result<[u8; 32], String> {
        let v = bs58::decode(s)
            .into_vec()
            .map_err(|e| format!("{s}: {e}"))?;
        v.try_into().map_err(|_| format!("{s}: not 32 bytes"))
    }

    /// An account, from `Debug`: Shipstern and Vixen print
    /// `XAccount { account: Variant(Type { .. }) }`. idl-verify wants the fields of `Type`.
    ///
    /// # Errors
    ///
    /// When the `Debug` text does not parse.
    pub fn account<T: std::fmt::Debug>(parsed: &T) -> Result<Value, String> {
        let v = strip_wrappers(super::debug::to_json(&format!("{parsed:?}"))?);
        Ok(match v.get("account") {
            Some(inner) => strip_wrappers(split_variant(inner.clone()).1),
            None => v,
        })
    }

    /// An instruction or event, from `Debug`: Shipstern and Vixen print
    /// `Instructions { instruction: Variant(..) }`, or `ProgramEventOutput { instruction: .. }`
    /// with `program-events`, and `Events { event: Variant { .. } }`.
    ///
    /// # Errors
    ///
    /// When the `Debug` text does not parse.
    pub fn instruction<T: std::fmt::Debug>(parsed: &T) -> Result<Value, String> {
        let mut v = super::debug::to_json(&format!("{parsed:?}"))?;
        while let Some(inner) = single_entry(&v)
            .and_then(|(_, body)| body.get("instruction").or_else(|| body.get("event")))
        {
            v = inner.clone();
        }
        let (name, body) = split_variant(v);
        let args = match strip_wrappers(body)
            .get("args")
            .cloned()
            .map(strip_wrappers)
        {
            // An args struct with no fields prints as its bare name.
            Some(Value::String(_)) | None => json!({}),
            Some(args) => args,
        };
        Ok(json!({ "name": name, "data": args }))
    }

    fn single_entry(v: &Value) -> Option<(&String, &Value)> {
        v.as_object()
            .filter(|m| m.len() == 1)
            .and_then(|m| m.iter().next())
    }

    /// `{"Variant": body}` from an externally tagged enum, split into name and body.
    fn split_variant(value: Value) -> (String, Value) {
        match value {
            Value::Object(map) if map.len() == 1 => map.into_iter().next().unwrap_or_default(),
            Value::String(name) => (name, json!({})),
            other => (String::new(), other),
        }
    }

    /// Drop `{"0": x}` and `{"TypeName": x}` layers around a struct body.
    fn strip_wrappers(mut v: Value) -> Value {
        loop {
            let inner = match &v {
                Value::Object(map) if map.len() == 1 => map.iter().next().and_then(|(k, inner)| {
                    let wrapper = k == "0" || k.starts_with(|c: char| c.is_ascii_uppercase());
                    (wrapper && inner.is_object()).then(|| inner.clone())
                }),
                _ => None,
            };
            match inner {
                Some(inner) => v = inner,
                None => return v,
            }
        }
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        /// Answers each kind in a fixed way, so the tests see only the protocol layer.
        struct Fixed;

        impl Decode for Fixed {
            fn account(
                &self,
                owner: [u8; 32],
                pubkey: [u8; 32],
                data: Vec<u8>,
            ) -> Result<Value, String> {
                Ok(json!({ "owner": owner[31], "pubkey": pubkey[31], "data": data }))
            }
            fn instruction(
                &self,
                _: [u8; 32],
                _: Vec<[u8; 32]>,
                _: Vec<u8>,
            ) -> Option<Result<Value, String>> {
                None
            }
            fn event(&self, _: &[u8]) -> Option<Result<Value, String>> {
                panic!("parser bug")
            }
        }

        fn replies(input: &str) -> Vec<Value> {
            let mut out = Vec::new();
            serve(&Fixed, input.as_bytes(), &mut out).unwrap();
            String::from_utf8(out)
                .unwrap()
                .lines()
                .map(|l| serde_json::from_str(l).unwrap())
                .collect()
        }

        const PROGRAM: &str = "11111111111111111111111111111112";

        #[test]
        fn each_reply_has_the_protocol_status() {
            let input = format!(
                "{{\"kind\":\"account\",\"program\":\"{PROGRAM}\",\"address\":\"\",\"data\":\"AQI=\"}}\n\
                 \n\
                 {{\"kind\":\"instruction\",\"program\":\"{PROGRAM}\",\"data\":\"\",\"accounts\":[\"{PROGRAM}\"]}}\n\
                 {{\"kind\":\"event\",\"program\":\"{PROGRAM}\",\"source\":\"cpi\",\"data\":\"Bw==\"}}\n\
                 {{\"kind\":\"account\",\"program\":\"{PROGRAM}\",\"address\":\"0OIl\",\"data\":\"\"}}\n\
                 {{\"kind\":\"account\",\"address\":\"\",\"data\":\"\"}}\n\
                 {{\"kind\":\"swap\",\"program\":\"{PROGRAM}\",\"data\":\"\"}}\n\
                 not json\n"
            );
            let got = replies(&input);
            assert_eq!(got.len(), 7, "an empty line gets no reply: {got:?}");
            // The protocol allows an empty address; the parser does not read it.
            assert_eq!(
                got[0],
                json!({"status": "ok", "value": {"owner": 1, "pubkey": 0, "data": [1, 2]}})
            );
            assert_eq!(got[1]["status"], "skip");
            assert!(got[1]["reason"]
                .as_str()
                .unwrap()
                .contains("InstructionParser"));
            // A panic in the parser is an error reply, so idl-verify still writes its report.
            assert!(got[2]["error"].as_str().unwrap().contains("parser bug"));
            for reply in &got[2..] {
                assert_eq!(reply["status"], "error", "{reply}");
            }
            assert!(got[4]["error"].as_str().unwrap().contains("no program"));
        }

        #[test]
        fn a_parser_that_waits_is_an_error() {
            assert_eq!(ready(async { 5 }), Ok(5));
            assert!(ready(std::future::pending::<()>())
                .unwrap_err()
                .contains("first poll"));
        }
    }
}

#[cfg(test)]
mod shipstern_shape_tests {
    use super::__private::{account, instruction};
    use serde_json::json;

    #[test]
    fn shipstern_wrappers_reduce_to_bodies() {
        // The shape Shipstern's generated outputs print in Debug.
        #[derive(Debug)]
        #[allow(dead_code)]
        struct DcaAccount {
            account: Option<Kind>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        enum Kind {
            Dca(Dca),
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Dca {
            idx: u64,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Instructions {
            instruction: Option<Ix>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        enum Ix {
            Close { accounts: Accts, args: CloseArgs },
        }
        #[derive(Debug)]
        struct Accts;
        #[derive(Debug)]
        #[allow(dead_code)]
        struct CloseArgs {
            amount: u64,
        }
        let parsed = DcaAccount {
            account: Some(Kind::Dca(Dca { idx: 3 })),
        };
        assert_eq!(account(&parsed).unwrap(), json!({"idx": 3}));
        let parsed = Instructions {
            instruction: Some(Ix::Close {
                accounts: Accts,
                args: CloseArgs { amount: 5 },
            }),
        };
        assert_eq!(
            instruction(&parsed).unwrap(),
            json!({"name": "Close", "data": {"amount": 5}})
        );
    }

    #[test]
    fn kind_structs_lose_their_type_name() {
        // Shipstern and Vixen 0.6 to 0.7 write an enum as a struct with one `kind` field.
        // idl-verify reads `{"kind": ..}` but not `{"Side": {"kind": ..}}`, which `Debug` adds.
        #[derive(Debug)]
        #[allow(dead_code)]
        struct PerpetualsAccount {
            account: Option<Kind>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        enum Kind {
            Position(Position),
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Position {
            side: Side,
            sides: Vec<Side>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Side {
            kind: Option<SideKind>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        enum SideKind {
            Long(SideLong),
        }
        #[derive(Debug)]
        struct SideLong;
        let long = || Side {
            kind: Some(SideKind::Long(SideLong)),
        };
        let parsed = PerpetualsAccount {
            account: Some(Kind::Position(Position {
                side: long(),
                sides: vec![long()],
            })),
        };
        let kind = json!({"kind": {"Long": {"0": "SideLong"}}});
        assert_eq!(
            super::__private::account(&parsed).unwrap(),
            json!({"side": kind, "sides": [kind]})
        );
    }

    #[test]
    fn program_events_outputs_reduce_to_name_and_args() {
        // With `program-events`, the instruction sits one wrapper deeper, and events print alike.
        #[derive(Debug)]
        #[allow(dead_code)]
        struct ProgramEventOutput {
            instruction: Option<Instructions>,
            program_events: Vec<Events>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Instructions {
            instruction: Option<Ix>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        enum Ix {
            Close { accounts: Accts, args: Amount },
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Events {
            event: Ev,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        enum Ev {
            Trade {
                accounts: TradeAccounts,
                args: Amount,
            },
        }
        #[derive(Debug)]
        struct Accts;
        #[derive(Debug)]
        #[allow(dead_code)]
        struct TradeAccounts {
            remaining_accounts: Vec<u8>,
        }
        #[derive(Debug)]
        #[allow(dead_code)]
        struct Amount {
            amount: u64,
        }
        let parsed = ProgramEventOutput {
            instruction: Some(Instructions {
                instruction: Some(Ix::Close {
                    accounts: Accts,
                    args: Amount { amount: 5 },
                }),
            }),
            program_events: Vec::new(),
        };
        assert_eq!(
            instruction(&parsed).unwrap(),
            json!({"name": "Close", "data": {"amount": 5}})
        );
        let event = Events {
            event: Ev::Trade {
                accounts: TradeAccounts {
                    remaining_accounts: Vec::new(),
                },
                args: Amount { amount: 9 },
            },
        };
        assert_eq!(
            instruction(&event).unwrap(),
            json!({"name": "Trade", "data": {"amount": 9}})
        );
    }
}
